const nw = msg.data.new_state;
if (!nw || !nw.attributes || !nw.attributes.lista) return null;

const lista = nw.attributes.lista;
const imie = nw.attributes.friendly_name ? nw.attributes.friendly_name.split(': ')[1] : "Uczeń";

let widzianeSygnatury = context.get('seen_term_sigs') || [];
let noweWpisy = [];
let aktualneSygnatury = [];

lista.forEach(item => {
    const sygnatura = `${item.data}_${item.przedmiot}_${item.typ}`;
    aktualneSygnatury.push(sygnatura);

    if (!widzianeSygnatury.includes(sygnatura)) {
        let ikona = (item.typ === 'Klasówka' || item.typ === 'Sprawdzian') ? '📝' : '🏠';
        noweWpisy.push({
            payload: {
                title: `${ikona} ${item.typ}: ${item.przedmiot}`,
                message: `### ${imie}\n**Termin:** ${item.data}\n**Opis:** ${item.opis}\n\n---\n**Autor:** ${item.autor}`,
                notification_id: "vultron_term_" + sygnatura.replace(/[^a-z0-9]/gi, '_')
            }
        });
    }
});

context.set('seen_term_sigs', aktualneSygnatury);

if (widzianeSygnatury.length === 0) {
    node.warn("Pierwsze uruchomienie terminarza - buforuję listę wpisów.");
    return null;
}

if (noweWpisy.length > 0) return [noweWpisy];
return null;
